function initialState(){return{studentName:'الطالب',currentLessonIndex:0,unlockedLessons:1,completedLessons:[],lessonProgress:{},exams:[],achievements:[]};}
function load(){try{const x=JSON.parse(localStorage.getItem(APP.storageKey));return x?{...initialState(),...x}:initialState();}catch(e){return initialState();}}
let state=load(),currentLesson=null,currentExam=null,answers=[],questionIndex=0,lastExam=null;
function save(){try{localStorage.setItem(APP.storageKey,JSON.stringify(state));}catch(e){console.warn(e);}}
function lessons(){return CURRICULUM.flatMap(u=>u.lessons.map(l=>({...l,unitId:u.id,unitNumber:u.number,unitTitle:u.title})));}
function lesson(id){return lessons().find(l=>l.id===id)||null;}
function indexOfLesson(id){return lessons().findIndex(l=>l.id===id);}
function clamp(v,a=0,b=100){return Math.min(Math.max(Number(v)||0,a),b);}
function pct(a,b){return b?Math.round(a/b*100):0;}
function esc(v){return String(v).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;');}
function progress(el,v){if(el)el.style.width=clamp(v)+'%';}
function toast(msg,type=''){const c=$('toastContainer');if(!c)return;const t=document.createElement('div');t.className='toast '+type;t.textContent=msg;c.appendChild(t);setTimeout(()=>{t.style.opacity='0';setTimeout(()=>t.remove(),250)},3000);}
function showModal(title,html,icon='💡',actions=[]){$('modalTitle').textContent=title;$('modalContent').innerHTML=html;$('modalIcon').textContent=icon;const box=$('modalActions');box.innerHTML='';actions.forEach(a=>{const b=document.createElement('button');b.className=a.className||'primary-button';b.type='button';b.textContent=a.text;b.onclick=()=>{closeModal();a.onClick?.()};box.appendChild(b)});$('modalLayer').classList.add('open');$('modalLayer').setAttribute('aria-hidden','false');}
function closeModal(){$('modalLayer').classList.remove('open');$('modalLayer').setAttribute('aria-hidden','true');}
function showScreen(id){const s=$(id);if(!s)return;$$('.screen').forEach(x=>x.classList.toggle('active-screen',x.id===id));$$('.navigation-item').forEach(x=>x.classList.toggle('active',x.dataset.screen===id));closeMenu();window.scrollTo({top:0,behavior:'smooth'});if(id==='homeScreen')renderHome();if(id==='unitsScreen')renderUnits();if(id==='examsScreen')renderHistory();if(id==='progressScreen')renderProgress();if(id==='achievementsScreen')renderAchievements();}
function openMenu(){$('sideMenu').classList.add('open');$('menuOverlay').classList.add('open');}
function closeMenu(){$('sideMenu').classList.remove('open');$('menuOverlay').classList.remove('open');}
function contentPct(){return pct(state.completedLessons.length,APP.totalLessons);}
function bookPct(){return Math.round(lessons().reduce((a,l)=>a+clamp(state.lessonProgress[l.id]||0),0)/APP.totalLessons);}
function avg(){return state.exams.length?Math.round(state.exams.reduce((a,e)=>a+e.percentage,0)/state.exams.length):0;}
function level(){const a=avg();if(!state.exams.length)return['لم يبدأ بعد','ابدأ أول اختبار ليظهر مستواك.',0];if(a<50)return['يحتاج دعمًا','راجع الدروس وحاول مرة أخرى.',a];if(a<65)return['ضعيف','تحتاج إلى مراجعة أكثر قبل الانتقال.',a];if(a<75)return['جيد','نتيجة جيدة! واصل المراجعة.',a];if(a<85)return['جيد جدًا','مستواك يتقدم بشكل رائع.',a];return['ممتاز','إيه الحلاوة دي! حافظ على مستواك.',a];}
