function renderHome(){dashboard();const l=lessons()[Math.min(state.unlockedLessons-1,APP.totalLessons-1)];if(!l)return;const p=clamp(state.lessonProgress[l.id]||0);$('currentLessonTitle').textContent=l.title;$('currentLessonDescription').textContent=l.subtitle;$('currentLessonProgressText').textContent=p+'%';progress($('currentLessonProgressBar'),p);$('currentLessonStatus').textContent=state.completedLessons.includes(l.id)?'✅ مكتمل':'🔓 متاح';$('continueLessonButton').textContent=state.completedLessons.includes(l.id)?'🔎 مراجعة الدرس':p?'▶️ استكمال المذاكرة':'🚀 ابدأ المذاكرة';const m=['أنت تقدر! كل خطوة تقربك من هدفك. 🌟','ركز في النقاط المهمة وبعدها ورّينا شطارتك! 💪','الاستمرارية سر التفوق. 🚀','ذاكر بهدوء، افهم الفكرة، وبعدها اختبر نفسك. 🧠'];$('motivationMessage').textContent=m[state.exams.length%m.length];const last=state.exams.at(-1);$('recentExamContent').innerHTML=last?`<div class="exam-history-card"><div class="exam-history-icon">${last.passed?'✅':'📚'}</div><div class="exam-history-info"><strong>${esc(last.lessonTitle)}</strong><span>${esc(last.unitTitle)}</span></div><strong>${last.score}/${last.total} (${last.percentage}%)</strong></div>`:`<div class="empty-state"><span>📝</span><h3>لسه مفيش اختبارات</h3><p>ذاكر أول درس وبعدها ابدأ اختبارك الأول.</p></div>`;renderHomeUnits();}
